from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.exception import LibraryError
import taf.ul.ettf.utils.exception_causes as exception_causes


logger = custom_logger('StateMachinery')


class StateMachineError(LibraryError):
    pass


def raise_error(cause, message):
    logger.error(message)
    raise StateMachineError(cause, message)


def assert_type(obj, expected_type):
    if not isinstance(obj, expected_type):
        raise_error(exception_causes.INVALID_TYPE,
                    'Incorrect type of transition map. Should be: {}. Is: {}'.format(expected_type, type(obj)))


class Event(object):
    pass


class State(with_metaclass(ABCMeta, object)):
    def process(self, event):
        pass

    @abstractmethod
    def finish(self):
        pass


class TransitionMap(object):
    def __init__(self, transitions):
        assert_type(transitions, expected_type=dict)
        self._transitions = transitions

    def get(self, event):
        return self._transitions[type(event)]

    def __contains__(self, event):
        return type(event) in self._transitions


class StateNotSet(State):
    def process(self, event):
        raise_error(exception_causes.INCORRECT_CONFIG,
                    'Could not process event. State is not set. Event: {}'.format(type(event)))

    def finish(self):
        pass


class Machinery(object):
    def __init__(self, transition_map):
        self._transition_map = TransitionMap(transition_map)
        self._active_state = StateNotSet()

    @property
    def active_state(self):
        return self._active_state

    def process(self, event):
        logger.debug('Machinery is processing event: {}'.format(event))
        if event in self._transition_map:
            self._transition(self._transition_map.get(event)())

        self._active_state.process(event)

    def finish(self):
        self._active_state.finish()
        logger.debug('Machinery finished')

    def _transition(self, state):
        self._active_state.finish()
        logger.debug('State transition. Old: {}. New: {}'.format(self._active_state, state))
        self._active_state = state
